fn largest_smallest_integers(arr: Vec<i8>) -> (Option<i8>, Option<i8>) {
    if arr.is_empty() {
        return (None, None);
    }

    // Initialize both max and min to the first element.
    let mut max_val = arr[0];
    let mut min_val = arr[0];

    // Scan the rest of the array exactly once.
    for &x in &arr[1..] {
        if x > max_val {
            max_val = x;
        } else if x < min_val {
            min_val = x;
        }
    }

    (Some(max_val), Some(min_val))
}

